import pytest

from bedrock_protocol import v1001, v2168

# generated by gophertunnel b8bd735:
# packet.ContainerClose{WindowID: 120, ContainerType: 18, ServerSide: true}
ARMOR = bytes.fromhex("781201")

# generated by gophertunnel b8bd735:
# packet.ContainerClose{WindowID: 255, ContainerType: 247, ServerSide: false}
NONE = bytes.fromhex("fff700")

GOLDENS = [
    pytest.param(
        v2168.ContainerClosePacket(
            container_id=v2168.ContainerID.ARMOR,
            container_type=v2168.ContainerType.ARMOR,
            server_initiated_close=True,
        ),
        ARMOR,
        id="armor",
    ),
    pytest.param(
        v2168.ContainerClosePacket(
            container_id=v2168.ContainerID.NONE,
            container_type=v2168.ContainerType.NONE,
            server_initiated_close=False,
        ),
        NONE,
        id="sentinels",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_container_close_is_packet_47(version):
    assert version.PACKETS[47] is version.ContainerClosePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_container_close_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_container_close_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
